import React, { useEffect, useState } from 'react';
import API from '../api/axios';

const ManageBookings = () => {
  const [bookings, setBookings] = useState([]);

  const fetchBookings = () => {
    API.get('/admin/bookings')
      .then(res => setBookings(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => { fetchBookings(); }, []);

  const handleStatusChange = async (id, status) => {
    try {
      await API.put(`/admin/bookings/${id}`, { status });
      alert(`Booking ${status}!`);
      fetchBookings();
    } catch (err) {
      alert('Error updating booking status.');
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <h1 className="text-2xl font-bold mb-6 text-slate-900">Manage Room Booking Requests</h1>

      <div className="bg-white rounded-xl shadow border overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-100 text-slate-700 text-sm">
              <th className="p-4">Requested By</th>
              <th className="p-4">Room / Venue</th>
              <th className="p-4">Date & Time</th>
              <th className="p-4">Purpose</th>
              <th className="p-4">Status</th>
              <th className="p-4">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y text-sm">
            {bookings.map((b) => (
              <tr key={b._id} className="hover:bg-slate-50">
                <td className="p-4">
                  <div className="font-bold">{b.bookedBy?.name}</div>
                  <div className="text-xs text-slate-500">{b.bookedBy?.rollNo}</div>
                </td>
                <td className="p-4 font-bold text-sky-600">{b.roomName}</td>
                <td className="p-4">
                  <div>📅 {b.date}</div>
                  <div className="text-xs text-slate-500">⏰ {b.startTime} - {b.endTime}</div>
                </td>
                <td className="p-4 text-slate-600">{b.purpose}</td>
                <td className="p-4">
                  <span className={`px-2.5 py-1 rounded text-xs font-extrabold ${
                    b.status === 'Approved' ? 'bg-emerald-100 text-emerald-800' :
                    b.status === 'Rejected' ? 'bg-red-100 text-red-800' : 'bg-amber-100 text-amber-800'
                  }`}>
                    {b.status}
                  </span>
                </td>
                <td className="p-4 space-x-2">
                  <button
                    onClick={() => handleStatusChange(b._id, 'Approved')}
                    className="bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-1 rounded text-xs font-bold"
                  >
                    Approve
                  </button>
                  <button
                    onClick={() => handleStatusChange(b._id, 'Rejected')}
                    className="bg-red-600 hover:bg-red-700 text-white px-3 py-1 rounded text-xs font-bold"
                  >
                    Reject
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ManageBookings;
